import { createElement } from 'react';
import type { ReactElement } from 'react';
import { renderToString as renderPreact } from 'preact-render-to-string';
import type { VNode } from 'preact';
import { IdPrefix } from './compat/react';
import { ISLAND_TAG, revive } from './islands';
import type { Encoded, Registry } from './islands';

export { ISLAND_TAG, SLOT_TAG, Slot, registryOf, revive } from './islands';
export type { Encoded, Registry } from './islands';
export { createElement };

type IslandOptions = {
  name: string;
  props: Encoded;
  id: string;
  slots?: Record<string, string>;
};

function render(element: ReactElement, id: string): string {
  return renderPreact(createElement(IdPrefix.Provider as never, { value: id }, element) as unknown as VNode);
}

export function renderIsland(registry: Registry, { name, props, id, slots = {} }: IslandOptions): string {
  const type = registry.get(name);
  if (!type) throw new Error(`540-ds: component "${name}" is not registered`);
  const slotHtml = (key: string) => {
    if (!(key in slots)) throw new Error(`540-ds: slot "${key}" has no HTML`);
    return slots[key];
  };
  const inner = render(createElement(type, revive(props, registry, slotHtml) as Record<string, unknown>), id);
  return `<${ISLAND_TAG} data-c="${escapeAttr(name)}" data-id="${escapeAttr(id)}" data-p="${escapeAttr(JSON.stringify(props))}">${inner}</${ISLAND_TAG}>`;
}

export function renderStatic(element: ReactElement, id: string): string {
  return render(element, id);
}

type RenderOptions = { identifierPrefix?: string };

/** Kept from the React runtime, so talk builds that call them keep working. */
export function renderToString(element: ReactElement, options: RenderOptions = {}): string {
  return render(element, options.identifierPrefix ?? '');
}

export const renderToStaticMarkup = renderToString;

function escapeAttr(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}
import { cloneElement, createElement, isValidElement, useEffect } from 'react';
import type { ComponentType, ReactNode } from 'react';

export type Encoded = string | number | boolean | null | Encoded[] | { [key: string]: Encoded };

export type Registry = Map<string, ComponentType<Record<string, unknown>>>;

export const ISLAND_TAG = 'ds-island';
export const SLOT_TAG = 'ds-slot';

type SlotProps = { id: string; html: string };

let onSlotMount: (() => void) | undefined;

/** Called whenever a Slot mounts: its HTML may hold islands that are new, unhydrated nodes. */
export function whenSlotMounts(callback: () => void) {
  onSlotMount = callback;
}

export function Slot({ id, html }: SlotProps) {
  // A Slot rebuilt on the client (a remount, a node created during hydration) writes its HTML again,
  // so the islands inside are new nodes: ask the runtime for another pass
  useEffect(() => {
    onSlotMount?.();
  }, []);
  return createElement(SLOT_TAG, { 'data-s': id, dangerouslySetInnerHTML: { __html: html } });
}

function isObject(value: unknown): value is Record<string, Encoded> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function revive(value: Encoded, registry: Registry, slotHtml: (id: string) => string): unknown {
  if (Array.isArray(value)) {
    return value.map((item, i) => {
      const node = revive(item, registry, slotHtml);
      return isObject(item) && ('$slot' in item || '$el' in item) ? withKey(node as ReactNode, i) : node;
    });
  }
  if (!isObject(value)) return value;
  if (typeof value.$slot === 'string') return createElement(Slot, { id: value.$slot, html: slotHtml(value.$slot) });
  if (typeof value.$el === 'string') {
    const name = value.$el;
    const type = /^[a-z]/.test(name) ? name : registry.get(name);
    if (!type) throw new Error(`540-ds: component "${name}" is not registered; include its island`);
    const props = revive(value.p ?? {}, registry, slotHtml) as Record<string, unknown>;
    return createElement(type, props);
  }
  const out: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value)) out[key] = revive(item, registry, slotHtml);
  return out;
}

function withKey(node: ReactNode, key: number): ReactNode {
  return isValidElement(node) ? cloneElement(node, { key: String(key) }) : node;
}

function isComponent(value: unknown): value is ComponentType<Record<string, unknown>> {
  return typeof value === 'function' || (typeof value === 'object' && value !== null && '$$typeof' in value);
}

/** Collects the components (exports whose name starts with a capital) of the given modules. */
export function registryOf(...modules: Record<string, unknown>[]): Registry {
  const registry: Registry = new Map();
  for (const mod of modules) {
    for (const [key, value] of Object.entries(mod)) if (/^[A-Z]/.test(key) && isComponent(value)) registry.set(key, value);
  }
  return registry;
